# small host parallel.
MIN_CORES_PER_AUTO_JOB = 2


def typecheck_command(project: TypecheckProject) -> list[str]:
    if project == "store-libsql":
        return TYPECHECK_CMD
    if project == "conformance":
        return CONFORMANCE_TYPECHECK_CMD
    raise ValueError(f"unknown mutation typecheck project {project!r}")


def mutation_vitest_targets(mutations: list[Mutation]) -> tuple[ExpectedVerdict, ...]:
    """The registered Vitest tests of the mutations that Vitest checks."""
    return tuple(mutation.verdict for mutation in mutations if mutation.typecheck_project is None)


def mutation_typecheck_projects(
    mutations: list[Mutation],
    *,
    routing_self_test_fault: str | None = None,
) -> tuple[TypecheckProject, ...]:
    projects: set[TypecheckProject] = set()
    for mutation in mutations:
        if mutation.typecheck_project is not None:
            projects.add(mutation.typecheck_project)
    ordered = tuple(project for project in TYPECHECK_PROJECT_ORDER if project in projects)
    if len(ordered) != len(projects):
        raise ValueError(f"unknown mutation typecheck projects {sorted(projects)!r}")
    if routing_self_test_fault == "skip-store-typecheck" and ordered == (
        "store-libsql",
    ):
        return ()
    if routing_self_test_fault == "misroute-store-typecheck" and ordered == (
        "store-libsql",
    ):
        return ("conformance",)
    if routing_self_test_fault == "duplicate-store-typecheck" and ordered == (
        "store-libsql",
    ):
        return ("store-libsql", "store-libsql")
    if routing_self_test_fault == "skip-conformance-typecheck" and ordered == (
        "conformance",
    ):
        return ()
    if routing_self_test_fault == "misroute-conformance-typecheck" and ordered == (
        "conformance",
    ):
        return ("store-libsql",)
    if routing_self_test_fault == "duplicate-conformance-typecheck" and ordered == (
        "conformance",
    ):
        return ("conformance", "conformance")
    if (
        routing_self_test_fault == "reverse-typecheck-project-order"
        and len(ordered) > 1
    ):
        return tuple(reversed(ordered))
    if routing_self_test_fault == "typecheck-behavior-only" and not ordered:
        return ("store-libsql",)
    if (
        routing_self_test_fault == "typecheck-vitest-construction-baseline"
        and not ordered
        and any(
            mutation.verdict.kind == "construction"
            and mutation.typecheck_project is None
            for mutation in mutations
        )
    ):
        return ("store-libsql",)
    return ordered


def relative_test_file(value: object) -> str:
    path = Path(str(value))
    if not path.is_absolute():
        return path.as_posix()
    try:
        return path.relative_to(ROOT).as_posix()
    except ValueError:
        return path.as_posix()


def parse_report(
    text: str,
    process_ok: bool,
    diagnostic: str,
    *,
    return_transport_as_domain: bool = False,
    targets: tuple[ExpectedVerdict, ...] | None = None,
) -> SuiteResult:
    """Turn Vitest's JSON reporter into only the evidence attribution needs.

    With `targets`, every registered test that did not pass or fail is a suite error.
    """
    try:
        report = json.loads(text)
    except (json.JSONDecodeError, TypeError) as error:
        message = f"missing or malformed Vitest JSON report: {error}"
        return reject_suite_transport(
            message,
            SuiteResult(
                process_ok,
                False,
                (),
                (message,),
                diagnostic,
            ),
            return_as_domain=return_transport_as_domain,
        )
    if not isinstance(report, dict) or not isinstance(report.get("success"), bool):
        message = "Vitest JSON report has no boolean success verdict"
        return reject_suite_transport(
            message,
            SuiteResult(
                process_ok,
                False,
                (),
                (message,),
                diagnostic,
            ),
            return_as_domain=return_transport_as_domain,
        )

    suite_errors: list[str] = []
    report_errors: list[str] = []

    def invalid_report(message: str) -> None:
        suite_errors.append(message)
        report_errors.append(message)

    counter_names = (
        "numTotalTestSuites",
        "numPassedTestSuites",
        "numFailedTestSuites",
        "numPendingTestSuites",
        "numTotalTests",
        "numPassedTests",
        "numFailedTests",
        "numPendingTests",
        "numTodoTests",
    )
    counters: dict[str, int] = {}
    for name in counter_names:
        value = report.get(name)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            invalid_report(f"Vitest JSON report has no nonnegative integer {name}")
        else:
            counters[name] = value
    if len(counters) == len(counter_names):
        if counters["numTotalTestSuites"] != (
            counters["numPassedTestSuites"]
            + counters["numFailedTestSuites"]
            + counters["numPendingTestSuites"]
        ):
            invalid_report("Vitest JSON report has contradictory suite counters")
        if counters["numTotalTests"] != (
            counters["numPassedTests"]
            + counters["numFailedTests"]
            + counters["numPendingTests"]
            + counters["numTodoTests"]
        ):
            invalid_report("Vitest JSON report has contradictory test counters")

    assertions: list[FailedAssertion] = []
    observed_tests = {"passed": 0, "failed": 0, "pending": 0, "todo": 0}
    ran_tests: set[tuple[str, str]] = set()
    results = report.get("testResults")
    if not isinstance(results, list):
        message = "Vitest JSON report has no testResults array"
        return reject_suite_transport(
            message,
            SuiteResult(
                process_ok,
                bool(report["success"]),
                (),
                (*suite_errors, message),
                diagnostic,
            ),
            return_as_domain=return_transport_as_domain,
        )
    for result in results:
        if not isinstance(result, dict):
            invalid_report("Vitest JSON report contains a non-object test result")
            continue
        name = result.get("name")
        if not isinstance(name, str):
            invalid_report("Vitest JSON test result has no string name")
            name = "(unknown file)"
        file = relative_test_file(name)
        file_status = result.get("status")
        if file_status not in ("passed", "failed"):
            invalid_report(f"{file}: invalid or missing file status")
        message = result.get("message")
        if not isinstance(message, str):
            invalid_report(f"{file}: missing string message")
            message = ""
        elif message:
            suite_errors.append(f"{file}: {message}")
        rows = result.get("assertionResults")
        if not isinstance(rows, list):
            invalid_report(f"{file}: missing assertionResults")
            continue
        failed_in_file = False
        for assertion in rows:
            if not isinstance(assertion, dict):
                invalid_report(f"{file}: contains a non-object assertion result")
                continue
            status = assertion.get("status")
            if not isinstance(status, str):
                invalid_report(f"{file}: assertion has invalid or missing status")
                continue
            if status in ("skipped", "disabled"):
                observed_tests["pending"] += 1
            elif status in observed_tests:
                observed_tests[status] += 1
            else:
                invalid_report(f"{file}: assertion has invalid or missing status")
                continue
            if status in ("passed", "failed") and isinstance(assertion.get("fullName"), str):
                ran_tests.add((file, assertion["fullName"]))
            if status != "failed":
                continue
            failed_in_file = True
            messages = assertion.get("failureMessages")
            full_name = assertion.get("fullName")
            if not isinstance(full_name, str):
                invalid_report(f"{file}: failed assertion has no string fullName")
                full_name = ""
            if messages is not None and (
                not isinstance(messages, list)
                or any(not isinstance(item, str) for item in messages)
            ):
                invalid_report(
                    f"{file}: failed assertion has invalid failureMessages"
                )
                messages = []
            assertions.append(
                FailedAssertion(
                    file,
                    full_name,
                    tuple(messages) if isinstance(messages, list) else (),
                )
            )
        if file_status == "failed":
            if not failed_in_file and not message:
                invalid_report(
                    f"{file}: failed file has no failed assertion or file error"
                )
        elif failed_in_file or message:
            invalid_report(
                f"{file}: passed file contains a failed assertion or file error"
            )

    if len(counters) == len(counter_names):
        observed_by_counter = {
            "numTotalTests": sum(observed_tests.values()),
            "numPassedTests": observed_tests["passed"],
            "numFailedTests": observed_tests["failed"],
            "numPendingTests": observed_tests["pending"],
            "numTodoTests": observed_tests["todo"],
        }
        for name, observed in observed_by_counter.items():
            if counters[name] != observed:
                invalid_report(
                    f"Vitest JSON report {name}={counters[name]} "
                    f"does not match {observed} assertion results"
                )
        expected_success = (
            counters["numFailedTestSuites"] == 0
            and counters["numFailedTests"] == 0
        )
        if results and bool(report["success"]) != expected_success:
            invalid_report(
                "Vitest JSON report success contradicts its failure counters"
            )
        elif bool(report["success"]) and not expected_success:
            invalid_report(
                "Vitest JSON report success contradicts its failure counters"
            )
    if targets is not None:
        suite_errors.extend(targeted_tests_not_run(ran_tests, targets))
    parsed = SuiteResult(
        process_ok,
        bool(report["success"]),
        tuple(assertions),
        tuple(suite_errors),
        diagnostic,
    )
    if report_errors:
        return reject_suite_transport(
            report_errors[0],
            parsed,
            return_as_domain=return_transport_as_domain,
        )
    return parsed


def diagnostic_tail(path: Path, limit: int = 16_384) -> str:
    with path.open("rb") as stream:
        stream.seek(0, os.SEEK_END)
        size = stream.tell()
        stream.seek(max(0, size - limit))
        return stream.read().decode(errors="replace").strip()


def require_verifier_capabilities(
    *,
    scope: ConfinedScope,
    workspace: IsolatedWorkspace,
    authority: WorkerAuthority,
) -> None:
    if (
        workspace.root != ROOT.resolve()
        or authority.worker_root != ROOT.resolve()
        or scope.memory_max <= 0
        or scope.cpu_quota <= 0
    ):
        raise RuntimeError("mutation verifier lacks its runtime safety capabilities")


def terminate_verifier_processes(processes: list[subprocess.Popen[bytes]]) -> None:
    """Terminate verifier process groups with the verifier graces."""
    terminate_process_groups(
        processes,
        term_grace_seconds=VERIFIER_TERM_GRACE_SECONDS,
        kill_grace_seconds=KILLED_GROUP_REAP_GRACE_SECONDS,
    )


def run_suite_process(
    command: list[str],
    *,
    output: object,
    wall_time_seconds: float,
    audit_lock: InheritedAuditLock,
    drop_audit_lock_inheritance: bool = False,
    drain_grace_seconds: float = PROCESS_GROUP_DRAIN_GRACE_SECONDS,
) -> int:
    """Run one verifier suite and own its whole process group.

    The wall-time limit bounds the leader. Once the leader exits, the group gets up
    to drain_grace_seconds to empty before cleanup terminates what remains, so a
    suite can take the wall-time limit plus the drain grace plus the verifier
    termination graces.
    """
    if not math.isfinite(wall_time_seconds) or wall_time_seconds <= 0:
        raise ValueError("suite wall-time limit must be finite and positive")
    validate_drain_grace(drain_grace_seconds)
    if prove_inherited_audit_lock(audit_lock.path, audit_lock.fd) != audit_lock:
        raise ValueError("mutation verifier audit-lock capability changed")
    previous_handlers = {
        signum: signal.getsignal(signum)
        for signum in (signal.SIGINT, signal.SIGTERM, signal.SIGHUP)
    }

    def interrupt(signum: int, _frame: object) -> None:
        raise AuditSignal(signum)

    for signum in previous_handlers:
        signal.signal(signum, interrupt)
    process: subprocess.Popen[bytes] | None = None
    try:
        process = subprocess.Popen(
            command,
            cwd=ROOT,
            stdout=output,
            stderr=subprocess.STDOUT,
            start_new_session=True,
            pass_fds=() if drop_audit_lock_inheritance else (audit_lock.fd,),
        )
        try:
            returncode = process.wait(timeout=wall_time_seconds)
        except subprocess.TimeoutExpired as error:
            raise SuiteInfrastructureError(
                f"suite wall-time limit of {wall_time_seconds:g}s exceeded"
            ) from error
        if wait_for_process_groups([process.pid], drain_grace_seconds):
            raise SuiteLiveDescendantsError(
                "suite process leader exited with live descendants after a "
                f"{drain_grace_seconds:g}s drain"
            )
        return returncode
    except BaseException:
        # The one cleanup of the verifier group, however the suite ended. A cleanup
        # that fails to reap is not repeated, so a worker's cleanup stays within one
        # verifier term and kill grace.
        if process is not None and process_group_exists(process.pid):
            # A coordinator may repeat its termination signal while the worker is
            # already reaping this independently-sessioned verifier. Defer those
            # repeats until the whole nested group is gone; otherwise the second
            # signal can abort cleanup and orphan a grandchild.
            interrupt_handlers = {signum: interrupt for signum in previous_handlers}
            with CleanupSignalShield(interrupt_handlers) as shield:
                terminate_verifier_processes([process])
            if shield.deferred_signum is not None:
                raise AuditSignal(shield.deferred_signum)
        raise
    finally:
        for signum, previous in previous_handlers.items():
            signal.signal(signum, previous)


VITEST_TITLE_METACHARACTER = re.compile(r"[\\^$.*+?()\[\]{}|/]")


def vitest_title_pattern(full_names: list[str]) -> str:
    """A Vitest `-t` pattern that matches exactly these full test names.

    Vitest reads `-t` as a JavaScript regular expression, so an unescaped `[libsql]`
    is a character class and matches nothing, and a run that matches nothing still
    exits 0. `re.escape` is not used because it also escapes characters that a
    JavaScript `u`-flag pattern rejects.
    """
    escaped = [
        VITEST_TITLE_METACHARACTER.sub(lambda match: "\\" + match.group(0), name)
        for name in full_names
    ]
    return f"^(?:{'|'.join(escaped)})$"


def targeted_test_arguments(targets: tuple[ExpectedVerdict, ...]) -> list[str]:
    """Vitest arguments that run only the registered tests of these verdicts."""
    files = list(dict.fromkeys(target.file for target in targets))
    names = list(dict.fromkeys(target.full_name for target in targets))
    return [*files, "-t", vitest_title_pattern(names)]


# The longest `-t` pattern one Vitest launch gets. Linux caps a single argument at
# 131072 bytes, so a baseline splits its targets across launches below this.
TARGETED_PATTERN_LIMIT_BYTES = 32_000


def targeted_chunks(targets: tuple[ExpectedVerdict, ...]) -> list[tuple[ExpectedVerdict, ...]]:
    """Split targets so each launch's `-t` pattern stays under the argument limit."""
    chunks: list[tuple[ExpectedVerdict, ...]] = []
    current: list[ExpectedVerdict] = []
    for target in targets:
        candidate = [*current, target]
        names = list(dict.fromkeys(item.full_name for item in candidate))
        if current and len(vitest_title_pattern(names).encode()) > TARGETED_PATTERN_LIMIT_BYTES:
            chunks.append(tuple(current))
            current = [target]
        else:
            current = candidate
    if current:
        chunks.append(tuple(current))
    return chunks


def targeted_tests_not_run(
    ran: set[tuple[str, str]], targets: tuple[ExpectedVerdict, ...]
) -> tuple[str, ...]:
    """Registered tests that did not pass or fail in a targeted run.

    A targeted test that was filtered out, skipped, or missing proves nothing about
    its guard, so each one is a suite error rather than a pass.
    """
    return tuple(
        f"targeted test did not run: {target.file} > {target.full_name}"
        for target in dict.fromkeys(targets)
        if (target.file, target.full_name) not in ran
    )


def run_suite(
    max_workers: int,
    *,
    scope: ConfinedScope,
    workspace: IsolatedWorkspace,
    authority: WorkerAuthority,
    return_transport_as_domain: bool = False,
    suite_wall_time_seconds: float | None = None,
    targets: tuple[ExpectedVerdict, ...] | None = None,
) -> SuiteResult:
    """Run Vitest over the whole suite, or only over the registered tests of `targets`."""
    require_verifier_capabilities(
        scope=scope,
        workspace=workspace,
        authority=authority,
    )
    with tempfile.TemporaryDirectory(prefix="durablerun-mutation-report-") as temporary:
        report = Path(temporary) / "vitest.json"
        log = Path(temporary) / "vitest.log"
        command = [*TEST_CMD]
        if targets is not None:
            targets = tuple(dict.fromkeys(targets))
            if not targets:
                raise ValueError("a targeted Vitest run needs at least one registered test")
            command.extend(targeted_test_arguments(targets))
        if max_workers is not None:
            command.extend(("--maxWorkers", str(max_workers)))
        command.extend(("--reporter=json", "--outputFile", str(report)))
        with log.open("wb") as output:
            returncode = run_suite_process(
                command,
                output=output,
                audit_lock=authority.audit_lock,
                wall_time_seconds=(
                    MUTATION_SUITE_WALL_TIME_SECONDS
                    if suite_wall_time_seconds is None
                    else suite_wall_time_seconds
                ),
            )
        diagnostic = diagnostic_tail(log)
        if not report.exists():
            message = "Vitest did not write its JSON report"
            return reject_suite_transport(
                message,
                SuiteResult(
                    returncode == 0,
                    False,
                    (),
                    (message,),
                    diagnostic,
                ),
                return_as_domain=return_transport_as_domain,
            )
        parsed = parse_report(
            report.read_text(),
            returncode == 0,
            diagnostic,
            return_transport_as_domain=return_transport_as_domain,
            targets=targets,
        )
        if returncode >= 0:
            return parsed
        message = f"Vitest terminated by signal {-returncode}"
        return reject_suite_transport(
            message,
            parsed,
            return_as_domain=return_transport_as_domain,
        )


SUITE_TIMEOUT_SELF_TEST_READY = (
    "mutation-probe suite-timeout self-test entered real run_suite"
)
SUITE_TIMEOUT_SELF_TEST_PASSED = (
    "mutation-probe suite-timeout self-test observed the suite wall-time limit"
)
SUITE_TIMEOUT_SELF_TEST_REJECTED = (
    "mutation-probe suite-timeout self-test rejected unauthenticated verifier"
)
# Each suite self-test fault and the argparse destination of the child it belongs to.
SUITE_SELF_TEST_FAULT_CHILDREN = {
    "immediate-magic-error": "suite_timeout_self_test_child",
    "reject-draining-group": "suite_drain_self_test_child",
    "wall-time-instead-of-descendant": "suite_linger_self_test_child",
}
SUITE_SELF_TEST_DEADLINE_SECONDS = 0.1
# A self-test child's last act: wait until `barrier` exists, or 30 seconds pass. The
# program that includes it imports `time` and binds `barrier`, which may be None.
BARRIER_WAIT_PROGRAM = """\
deadline = time.monotonic() + 30
while time.monotonic() < deadline and not (barrier is not None and barrier.exists()):
    time.sleep(0.01)
"""

SUITE_SELF_TEST_DESCENDANT_PROGRAM = """\
import json, os, pathlib, signal, sys, time
signal.signal(signal.SIGTERM, signal.SIG_IGN)
stream = pathlib.Path(sys.argv[2]).open("a")
stream.write(
    json.dumps({"label": sys.argv[1], "leader": int(sys.argv[3]), "descendant": os.getpid()})
    + "\\n"
)
stream.flush()
os.fsync(stream.fileno())
stream.close()
barrier = pathlib.Path(sys.argv[4]) if len(sys.argv) > 4 else None
""" + BARRIER_WAIT_PROGRAM


def suite_self_test_command(
    label: str,
    state_path: Path,
    *,
    leader_exits: bool = False,
    barrier: Path | None = None,
) -> list[str]:
    parent_program = (
        "import os,pathlib,subprocess,sys,time; "
        "child=subprocess.Popen([sys.executable,'-c',sys.argv[3],"
        "sys.argv[1],sys.argv[2],str(os.getpid()),*sys.argv[4:]]); "
        "deadline=time.monotonic()+2; path=pathlib.Path(sys.argv[2]); "
        "needle='\"label\": \"'+sys.argv[1]+'\"'; "
        "ready=False; "
        "exec(\"while time.monotonic() < deadline:\\n"
        " if path.exists() and needle in path.read_text():\\n"
        "  ready=True; break\\n"
        " time.sleep(0.01)\"); "
        "assert ready, 'descendant did not authenticate readiness'; "
        + ("pass" if leader_exits else "time.sleep(30)")
    )
    return [
        sys.executable,
        "-c",
        parent_program,
        label,
        str(state_path),
        SUITE_SELF_TEST_DESCENDANT_PROGRAM,
        *(() if barrier is None else (str(barrier),)),
    ]


def suite_self_test_records(state_path: Path) -> list[dict[str, object]]:
    if not state_path.exists():
        return []
    records: list[dict[str, object]] = []
    for line in state_path.read_text().splitlines():
        try:
            record = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(record, dict):
            records.append(record)
    return records


def suite_self_test_record(
    state_path: Path,
    label: str,
) -> tuple[tuple[int, int] | None, str | None]:
    matches = [
        record
        for record in suite_self_test_records(state_path)
        if record.get("label") == label
    ]
    if len(matches) != 1:
        return None, f"{label} verifier wrote {len(matches)} authenticated PID records"
    leader = matches[0].get("leader")
    descendant = matches[0].get("descendant")
    if (
        not isinstance(leader, int)
        or isinstance(leader, bool)
        or leader <= 1
        or not isinstance(descendant, int)
        or isinstance(descendant, bool)
        or descendant <= 1
        or leader == descendant
    ):
        return None, f"{label} verifier wrote malformed process identities"
    return (leader, descendant), None


def cleanup_suite_self_test_records(state_path: Path) -> None:
    groups: set[int] = set()
    processes: set[int] = set()
    for record in suite_self_test_records(state_path):
        leader = record.get("leader")
        descendant = record.get("descendant")
        if not isinstance(leader, int) or isinstance(leader, bool) or leader <= 1:
            continue
        if leader == os.getpgrp():
            continue
        if isinstance(descendant, int) and not isinstance(descendant, bool):
            processes.add(descendant)
            try:
                if os.getpgid(descendant) == leader:
                    groups.add(leader)
            except ProcessLookupError:
                pass
        try:
            if os.getpgid(leader) == leader:
                groups.add(leader)
        except ProcessLookupError:
            pass
    for group in groups:
        try:
            os.killpg(group, signal.SIGKILL)
        except ProcessLookupError:
            pass
    deadline = time.monotonic() + 2
    while any(process_id_is_live(process) for process in processes) and time.monotonic() < deadline:
        time.sleep(0.02)


def suite_self_test_fixture() -> tuple[
    ConfinedScope,
    IsolatedWorkspace,
    WorkerAuthority,
    object,
]:
    audit_lock_stream = tempfile.NamedTemporaryFile(
        mode="a+",
        prefix="durablerun-suite-audit-lock-",
    )
    fcntl.flock(audit_lock_stream, fcntl.LOCK_EX | fcntl.LOCK_NB)
    os.set_inheritable(audit_lock_stream.fileno(), True)
    audit_lock = prove_inherited_audit_lock(
        Path(audit_lock_stream.name),
        audit_lock_stream.fileno(),
    )
    return (
        ConfinedScope("suite-timeout-self-test", 1, 1, 1),
        IsolatedWorkspace(ROOT.resolve()),
        WorkerAuthority(
            ROOT.resolve(),
            ROOT.resolve(),
            0,
            "a" * 40,
            "suite-timeout-self-test",
            audit_lock,
        ),
        audit_lock_stream,
    )


def suite_timeout_self_test_child(
    state_path: Path,
    fault: str | None,
) -> int:
    """Exercise both real verifier paths through their production default."""
    global MUTATION_SUITE_WALL_TIME_SECONDS
    original_test_command = TEST_CMD[:]
    original_typecheck_command = TYPECHECK_CMD[:]
    suite_defaults = run_suite.__kwdefaults__
    typecheck_defaults = run_typecheck.__kwdefaults__
    original_process_runner = run_suite_process
    original_wall_time = MUTATION_SUITE_WALL_TIME_SECONDS
    problems: list[str] = []
    if (
        suite_defaults is None
        or suite_defaults.get("suite_wall_time_seconds") is not None
        or typecheck_defaults is None
        or typecheck_defaults.get("suite_wall_time_seconds") is not None
        or MUTATION_SUITE_WALL_TIME_SECONDS != 600.0
    ):
        problems.append("Vitest and typecheck do not share the production 600s default")
    MUTATION_SUITE_WALL_TIME_SECONDS = SUITE_SELF_TEST_DEADLINE_SECONDS
    if fault == "immediate-magic-error":
        def immediate_magic_error(*_args: object, **_kwargs: object) -> int:
            raise SuiteInfrastructureError("suite wall-time limit exceeded")

        globals()["run_suite_process"] = immediate_magic_error
    (
        fixture_scope,
        fixture_workspace,
        fixture_authority,
        fixture_audit_lock,
    ) = suite_self_test_fixture()
    try:
        runners = (
            (
                "vitest",
                TEST_CMD,
                lambda: run_suite(
                    1,
                    scope=fixture_scope,
                    workspace=fixture_workspace,
                    authority=fixture_authority,
                ),
            ),
            (
                "typecheck",
                TYPECHECK_CMD,
                lambda: run_typecheck(
                    None,
                    project="store-libsql",
                    scope=fixture_scope,
                    workspace=fixture_workspace,
                    authority=fixture_authority,
                ),
            ),
        )
        for label, command, run in runners:
            command[:] = suite_self_test_command(label, state_path)
            try:
                run()
            except SuiteInfrastructureError as error:
                if "suite wall-time limit" not in str(error):
                    problems.append(f"{label} raised the wrong infrastructure failure: {error}")
            except Exception as error:
                problems.append(f"{label} raised the wrong exception: {error}")
            else:
                problems.append(f"{label} sleeping verifier returned without its deadline")
            identity, identity_problem = suite_self_test_record(state_path, label)
            if identity_problem is not None:
                problems.append(identity_problem)
            elif identity is not None and any(process_id_is_live(pid) for pid in identity):
                problems.append(f"{label} deadline left its verifier process group live")
    finally:
        cleanup_suite_self_test_records(state_path)
        TEST_CMD[:] = original_test_command
        TYPECHECK_CMD[:] = original_typecheck_command
        globals()["run_suite_process"] = original_process_runner
        MUTATION_SUITE_WALL_TIME_SECONDS = original_wall_time
        fixture_audit_lock.close()
    if problems:
        print(f"{SUITE_TIMEOUT_SELF_TEST_REJECTED}: {problems[0]}", file=sys.stderr)
        return 1
    print(SUITE_TIMEOUT_SELF_TEST_PASSED)
    return 0


DrainWait = Callable[[list[int], float], list[int]]


@contextlib.contextmanager
def drain_wait_replaced(
    replacement: Callable[[DrainWait, list[int], float], list[int]],
) -> Iterator[None]:
    """Make both runners wait for group drains through replacement.

    The replacement receives the wait that was in place when the swap began.
    """
    original_wait = wait_for_process_groups

    def replaced(groups: list[int], grace_seconds: float) -> list[int]:
        return replacement(original_wait, groups, grace_seconds)

    globals()["wait_for_process_groups"] = replaced
    try:
        yield
    finally:
        globals()["wait_for_process_groups"] = original_wait


def barrier_released_on_drain(
    barrier: Path, *, after_check: bool = False
) -> contextlib.AbstractContextManager[None]:
    """Create barrier when cleanup starts waiting for groups to drain.

    A self-test child that waits on the barrier exits exactly once the runner has
    seen its leader exit, so the case does not race a fixed child lifetime
    against the runner's polling. With after_check, the barrier appears only once
    the drain has returned, so a check with no drain always sees the group live
    and the child still exits a moment later.
    """
    def release_around_wait(
        real_wait: DrainWait, groups: list[int], grace_seconds: float
    ) -> list[int]:
        if not after_check:
            barrier.touch()
        try:
            return real_wait(groups, grace_seconds)
        finally:
            if after_check:
                barrier.touch()

    return drain_wait_replaced(release_around_wait)


def suite_self_test_verifier_run(
    state_path: Path,
    label: str,
    *,
    descendant: Literal["lingers", "drains", "drains-after-check"],
    drain_grace_seconds: float,
    wall_time_seconds: float = 1.0,
    leader_exits: bool = True,
) -> tuple[int | SuiteInfrastructureError | None, list[str]]:
    """Run a verifier whose descendant outlives its leader's readiness, and check what it left.

    A lingering descendant never exits. A draining one waits on a barrier released
    around the drain, as barrier_released_on_drain describes. Returns the runner's
    exit code, its infrastructure error, or None if it raised anything else, with
    the problems found in the verifier's records and processes. With leader_exits
    False the leader keeps running after its descendant records itself.
    """
    problems: list[str] = []
    outcome: int | SuiteInfrastructureError | None = None
    _, _, fixture_authority, fixture_audit_lock = suite_self_test_fixture()
    try:
        with tempfile.TemporaryDirectory(prefix=f"durablerun-suite-{label}-") as temporary:
            barrier = None if descendant == "lingers" else Path(temporary) / "barrier"
            command = suite_self_test_command(
                label, state_path, leader_exits=leader_exits, barrier=barrier
            )
            release = (
                contextlib.nullcontext()
                if barrier is None
                else barrier_released_on_drain(
                    barrier, after_check=descendant == "drains-after-check"
                )
            )
            with (Path(temporary) / "suite.log").open("wb") as output, release:
                try:
                    outcome = run_suite_process(
                        command,
                        output=output,
                        wall_time_seconds=wall_time_seconds,
                        audit_lock=fixture_authority.audit_lock,
                        drain_grace_seconds=drain_grace_seconds,
                    )
                except SuiteInfrastructureError as error:
                    outcome = error
                except Exception as error:
                    problems.append(f"{label} verifier raised the wrong exception: {error}")
        identity, identity_problem = suite_self_test_record(state_path, label)
        if identity_problem is not None:
            problems.append(identity_problem)
        elif identity is not None and any(process_id_is_live(pid) for pid in identity):
            problems.append(f"{label} verifier left its descendant live")
    finally:
        cleanup_suite_self_test_records(state_path)
        fixture_audit_lock.close()
    return outcome, problems


def verifier_cleanup_once_problems(temporary: Path) -> list[str]:
    """A verifier cleanup that fails to reap its group is not run a second time.

    A second run doubles the time a worker spends cleaning up, past the coordinator's
    termination grace for that worker.
    """
    global terminate_verifier_processes
    original = terminate_verifier_processes
    calls: list[list[subprocess.Popen[bytes]]] = []

    def unreapable_once(processes: list[subprocess.Popen[bytes]]) -> None:
        calls.append(list(processes))
        if len(calls) > 1:
            original(processes)
            return
        raise RuntimeError("cannot reap descendant process groups after SIGKILL: [fixture]")

    state_path = temporary / "cleanup-once.jsonl"
    problems: list[str] = []
    _, _, fixture_authority, fixture_audit_lock = suite_self_test_fixture()
    terminate_verifier_processes = unreapable_once
    try:
        with (temporary / "cleanup-once.log").open("wb") as output:
            try:
                run_suite_process(
                    suite_self_test_command("cleanup-once", state_path, leader_exits=True),
                    output=output,
                    wall_time_seconds=10.0,
                    audit_lock=fixture_authority.audit_lock,
                    drain_grace_seconds=0.0,
                )
                problems.append("process cleanup: an unreapable verifier group was accepted")
            except RuntimeError:
                pass
    finally:
        terminate_verifier_processes = original
        if len(calls) == 1:
            original(calls[0])
        cleanup_suite_self_test_records(state_path)
        fixture_audit_lock.close()
    if len(calls) != 1:
        problems.append(
            f"process cleanup: a verifier cleanup that failed to reap ran {len(calls)} times"
        )
    return problems


def suite_linger_self_test_child(state_path: Path, fault: str | None) -> int:
    """An exited verifier leader whose descendant never exits must be rejected and reaped.

    Under wall-time-instead-of-descendant the leader keeps running after its
    descendant records itself, so the verifier hits a 0.5 s wall-time limit instead.
    That infrastructure error must not pass for the rejection.
    """
    if fault not in (None, "wall-time-instead-of-descendant"):
        raise ValueError(f"unknown suite linger self-test fault: {fault}")
    wall_time_fault = fault == "wall-time-instead-of-descendant"
    outcome, problems = suite_self_test_verifier_run(
        state_path,
        "linger",
        descendant="lingers",
        # The descendant never exits, so any drain only spends lint-selftest's 1.5s
        # watchdog budget.
        drain_grace_seconds=0.0,
        wall_time_seconds=0.5 if wall_time_fault else 1.0,
        leader_exits=not wall_time_fault,
    )
    if isinstance(outcome, int):
        problems.insert(0, "exited verifier leader was accepted with a live descendant")
    elif isinstance(outcome, SuiteInfrastructureError) and not isinstance(
        outcome, SuiteLiveDescendantsError
    ):
        problems.insert(0, f"exited verifier leader was rejected for another reason: {outcome}")
    if problems:
        print(f"mutation-probe suite-linger self-test: {problems[0]}", file=sys.stderr)
        return 1
    print("mutation-probe suite-linger self-test reaped the exited leader's group")
    return 0


def suite_drain_self_test_child(state_path: Path, fault: str | None) -> int:
    """A verifier group that drains just after its leader exits must be accepted.

    Under reject-draining-group the runner checks with no drain, and the barrier
    appears only after that check, so the group is live when it is checked.
    """
    if fault not in (None, "reject-draining-group"):
        raise ValueError(f"unknown suite drain self-test fault: {fault}")
    no_drain = fault == "reject-draining-group"
    outcome, problems = suite_self_test_verifier_run(
        state_path,
        "drain",
        descendant="drains-after-check" if no_drain else "drains",
        # Short enough that a group that never drains is reported by name inside
        # lint-selftest's 1.5s watchdog.
        drain_grace_seconds=0.0 if no_drain else 0.5,
    )
    if isinstance(outcome, SuiteLiveDescendantsError):
        problems.insert(
            0,
            f"a verifier group that drains after its leader exits was rejected: {outcome}",
        )
    elif isinstance(outcome, SuiteInfrastructureError):
        problems.insert(0, f"a draining verifier group was rejected for another reason: {outcome}")
    elif isinstance(outcome, int) and outcome != 0:
        problems.insert(0, f"draining verifier leader exited {outcome}")
    if problems:
        print(f"mutation-probe suite-drain self-test: {problems[0]}", file=sys.stderr)
        return 1
    print(
        "mutation-probe suite-drain self-test accepted a verifier group that drained "
        "after its leader exited"
    )
    return 0


def suite_interrupt_self_test_child(state_path: Path) -> int:
    original_command = TEST_CMD[:]
    TEST_CMD[:] = suite_self_test_command("interrupt", state_path)
    (
        fixture_scope,
        fixture_workspace,
        fixture_authority,
        fixture_audit_lock,
    ) = suite_self_test_fixture()
    try:
        run_suite(
            1,
            scope=fixture_scope,
            workspace=fixture_workspace,
            authority=fixture_authority,
        )
    finally:
        TEST_CMD[:] = original_command
        fixture_audit_lock.close()
    print("mutation-probe suite-interrupt self-test returned without its external signal")
    return 1


COMPILER_ERROR_PATTERN = re.compile(r"(?m)^(.+?\.tsx?)\((\d+),(\d+)\): error TS(\d+):.*$")
# A project error, such as a missing configuration file, has no file position.
COMPILER_PROJECT_ERROR_PATTERN = re.compile(r"(?m)^error TS\d+:.*$")


def compiler_errors(compiler_output: str) -> tuple[str, list[re.Match[str]]]:
    """The compiler output without ANSI colors, and its located error lines."""
    plain = re.sub(r"\x1b\[[0-9;]*m", "", compiler_output)
    return plain, list(COMPILER_ERROR_PATTERN.finditer(plain))


def typecheck_baseline_failure(compiler_output: str, diagnostic: str) -> SuiteResult:
    """A red unmutated compiler leg, named by the compiler's own error lines.

    Project errors come first, since located errors often follow from them. Output
    with neither, such as a crashed compiler, is named by its last lines instead.
    """
    plain, located = compiler_errors(compiler_output)
    named = [
        *COMPILER_PROJECT_ERROR_PATTERN.findall(plain),
        *(error.group(0) for error in located),
    ] or [line for line in plain.splitlines() if line.strip()][-20:]
    return SuiteResult(
        False,
        False,
        (),
        ("the unmutated TypeScript construction baseline failed", *named[:20]),
        diagnostic,
    )


def run_typecheck(
    expected: ExpectedVerdict | None,
    *,
    project: TypecheckProject,
    scope: ConfinedScope,
    workspace: IsolatedWorkspace,
    authority: WorkerAuthority,
    suite_wall_time_seconds: float | None = None,
) -> SuiteResult:
    """Run the compiler leg and attribute only the intended unused-error directive."""
    require_verifier_capabilities(
        scope=scope,
        workspace=workspace,
        authority=authority,
    )
    with tempfile.TemporaryDirectory(prefix="durablerun-mutation-typecheck-") as temporary:
        log = Path(temporary) / "tsc.log"
        with log.open("wb") as output:
            returncode = run_suite_process(
                typecheck_command(project),
                output=output,
                audit_lock=authority.audit_lock,
                wall_time_seconds=(
                    MUTATION_SUITE_WALL_TIME_SECONDS
                    if suite_wall_time_seconds is None
                    else suite_wall_time_seconds
                ),
            )
        compiler_output = log.read_text(errors="replace")
        diagnostic = diagnostic_tail(log)
    if returncode == 0:
        return SuiteResult(True, True, (), (), diagnostic)
    if expected is None:
        return typecheck_baseline_failure(compiler_output, diagnostic)

    marker_file = expected.marker_file or expected.file
    verdict_source = (ROOT / marker_file).read_text()
    try:
        marker_analysis = analyze_typescript_sources({marker_file: verdict_source})[
            marker_file
        ]
    except ValueError as error:
        return SuiteResult(
            False,
            False,
            (),
            (f"{marker_file}: cannot inspect construction marker: {error}",),
            diagnostic,
        )
    if marker_analysis.diagnostics:
        return SuiteResult(
            False,
            False,
            (),
            (
                f"{marker_file}: cannot own a construction marker: "
                f"{marker_analysis.diagnostics}",
            ),
            diagnostic,
        )
    marker_lines = [
        line
        for marker, line in marker_analysis.expect_error_verdict_markers
        if marker == expected.marker
    ]
    if len(marker_lines) != 1:
        return SuiteResult(
            False,
            False,
            (),
            (
                f"{marker_file}: expected one compiler-owned @ts-expect-error marker, "
                f"found {len(marker_lines)}",
            ),
            diagnostic,
        )
    marker_line = marker_lines[0]

    _, located_errors = compiler_errors(compiler_output)
    wanted = (marker_file, str(marker_line), "2578")

    def relative_compiler_path(path: str) -> str:
        candidate = Path(path.strip())
        if not candidate.is_absolute():
            candidate = ROOT / candidate
        try:
            return candidate.resolve().relative_to(ROOT.resolve()).as_posix()
        except ValueError:
            return candidate.resolve().as_posix()

    observed = [
        (relative_compiler_path(path), line, code)
        for path, line, _column, code in (error.groups() for error in located_errors)
    ]
    if observed != [wanted]:
        return SuiteResult(
            False,
            False,
            (),
            (
                f"TypeScript construction mutation produced {observed}, "
                f"expected only {wanted}",
            ),
            diagnostic,
        )
    return SuiteResult(
        False,
        False,
        (FailedAssertion(expected.file, expected.full_name, (expected.marker,)),),
        (),
        diagnostic,
    )


VerdictOutcome = Literal["caught", "caught-with-collateral", "survived", "wrong-path"]


def mutation_is_caught(outcome: object) -> bool:
    return outcome in ("caught", "caught-with-collateral")


def message_has_exact_marker(marker: str, message: str) -> bool:
    """Match the emitted diagnostic, never a later stack/source excerpt."""
    first_line = message.splitlines()[0].strip() if message else ""
    return (
        first_line == marker
        or first_line == f"Error: {marker}"
        or first_line == f"AssertionError: {marker}"
        or first_line.startswith(f"AssertionError: {marker}:")
    )


def assertion_matches(expected: ExpectedVerdict, actual: FailedAssertion) -> bool:
    return (
        actual.file == expected.file
        and actual.full_name == expected.full_name
        and any(message_has_exact_marker(expected.marker, message) for message in actual.messages)
    )


def classify_verdict(
    result: SuiteResult,
    expected: ExpectedVerdict,
    matcher=assertion_matches,
    *,
    accept_suite_error: bool = False,
    accept_incoherent: bool = False,
    accept_malformed: bool = False,
    accept_collateral_assertion: bool = False,
    accept_collateral_message: bool = False,
) -> VerdictOutcome:
    if result.green:
        return "survived"
    # A real Vitest failure has both a nonzero process exit and success=false.
    # A signal, broken reporter, or contradictory result is infrastructure, not
    # evidence that the intended guard was exercised.
    if not accept_incoherent and (result.process_ok or result.report_ok):
        return "wrong-path"
    malformed = any(
        "missing or malformed" in error or "did not write" in error for error in result.suite_errors
    )
    if result.suite_errors:
        if malformed and accept_malformed:
            return "caught"
        if accept_suite_error and any(expected.marker in error for error in result.suite_errors):
            return "caught"
        return "wrong-path"
    owners = [assertion for assertion in result.assertions if matcher(expected, assertion)]
    if len(owners) != 1 or any(not assertion.messages for assertion in result.assertions):
        return "wrong-path"
    if not accept_collateral_message and len(owners[0].messages) != 1:
        return "wrong-path"
    if len(result.assertions) > 1 and not accept_collateral_assertion:
        return "caught-with-collateral"
    return "caught"


